-- Load dynamic Matugen colors if available
local dynamic_colors = (function()
    local ok, c = pcall(dofile, (os.getenv("HOME") or "/home/kimmi") .. "/.config/hypr/colors.lua")
    if ok and type(c) == "table" then return c end
    return {
        active_border = { colors = {"rgba(33ccffee)", "rgba(00ff99ee)"}, angle = 45 },
        inactive_border = "rgba(595959aa)",
    }
end)()

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 8,

        border_size = 1,

        col = {
            active_border   = dynamic_colors.active_border,
            inactive_border = dynamic_colors.inactive_border,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 8,
        rounding_power = 2,

        -- Frosted glass transparency
        active_opacity   = 0.88,
        inactive_opacity = 0.78,

        shadow = {
            enabled      = true,
            range        = 12,
            render_power = 3,
            color        = 0x88000000,
        },

        blur = {
            enabled           = true,
            size              = 6,
            passes            = 3,
            new_optimizations = true,
            vibrancy          = 0.2,
            noise             = 0.01,
            contrast          = 1.0,
            brightness        = 0.9,
            popups            = true,
            special           = true,
            ignore_opacity    = true,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Snappy, responsive animation curves
hl.curve("snappy",     { type = "bezier", points = { {0.16, 1}, {0.3, 1} } })
hl.curve("fastEase",   { type = "bezier", points = { {0.05, 0.9}, {0.1, 1.05} } })
hl.curve("linear",     { type = "bezier", points = { {0, 0}, {1, 1} } })

hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "snappy" })
hl.animation({ leaf = "border",        enabled = true,  speed = 4,    bezier = "snappy" })
hl.animation({ leaf = "windows",       enabled = true,  speed = 3.5,  bezier = "snappy" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 3.0,  bezier = "snappy",       style = "popin 90%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 2.2,  bezier = "snappy",       style = "popin 95%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 2.0,  bezier = "snappy" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 1.8,  bezier = "snappy" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 2.2,  bezier = "snappy" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 2.8,  bezier = "snappy" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 2.5,  bezier = "snappy",       style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 1.8,  bezier = "snappy",       style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 2.0,  bezier = "snappy" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 1.6,  bezier = "snappy" })
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 3.2,  bezier = "snappy",       style = "slide" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 3.0,  bezier = "snappy",       style = "slide" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 3.0,  bezier = "snappy",       style = "slide" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 8,    bezier = "snappy" })

